        // Deploy an adversarial receiver that ALWAYS reverts on receive; this is necessary because
        // a raw fuzzed address is an EOA and will accept transfers silently. The bug routes funds
        // to owner instead of receiver and thus will not trigger the revert, while the reference
        // routes to receiver and will revert when receiver rejects funds. We fuzz which address
        // the fuzzer picks; if it equals the deployed Reverter, invoke the failing path.
        Reverter rev = new Reverter();

        // Choose the actual target address: if the fuzzed receiver equals address(0) or equals address(this)
        // or any arbitrary, we still allow it; the fuzzer can hit rev by passing its address.
        address target = receiver;

        // fund the contract and owner so transfers are possible
        // c was deployed by this test; its owner is address(this). Give c some balance to send.
        vm.deal(address(c), 1 ether);

        // Make caller the owner: c.owner is deployer (this contract), so we call as this contract.
        // Call c.sendTo with value-less call (transfer uses contract balance), but if receiver is a
        // contract that reverts on receive, the reference will revert. We capture whether the call succeeds.
        bool ok;
        try c.sendTo{gas: gasleft()}(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property we assert: for the correct contract, if the target rejects receiving funds
        // (i.e., target == address(rev)), then the call must revert (ok == false). The mutant that sends
        // to owner instead of receiver will not revert in that case, so the assertion distinguishes them.
        if (target == address(rev)) {
            assertTrue(!ok);
        } else {
            // For other targets (EOAs or accepting contracts), the call should succeed (ok == true)
            // and we assert that condition to keep the domain well-defined.
            assertTrue(ok);
        }
    }
}

// adversarial helper that reverts on receive so transfers to it always fail
contract Reverter {
    receive() external payable {
        revert("no funds");
    }
}

